import{c as s,Z as p,Q as d,j as e,m as o,g as t,n as i,o as a,av as n}from"./chunks/framework.rWdQudnF.js";const R=JSON.parse('{"title":"Hello World!","description":"","frontmatter":{"title":"Hello World!"},"headers":[],"relativePath":"案例分析/软件工程真题回顾/Hello World!.md","filePath":"案例分析/软件工程真题回顾/Hello World!.md","lastUpdated":null}'),u={name:"案例分析/软件工程真题回顾/Hello World!.md"};function f(g,l,m,b,h,k){const r=p("font");return d(),e("div",null,[l[32]||(l[32]=o('<p>结构化建模，即数据流图和R图，当然UML(用例图、类图、序列图等)也需要掌握，如果超纲那就多研究，多做历年案例题，掌握超纲题技巧。</p><p>综合那里的笔记应该是有很大问题，<a href="/arch-exam/综合知识/软件工程/需求工程.html">架构师-备考 软件工程-需求工程</a> 这一章看起来内容也没对上，有空整理一下了。</p><h3 id="结构化三大模型" tabindex="-1">结构化三大模型 <a class="header-anchor" href="#结构化三大模型" aria-label="Permalink to &quot;结构化三大模型&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234233.png" alt="image.png"></p><h4 id="功能模型-数据流图" tabindex="-1">功能模型（数据流图) <a class="header-anchor" href="#功能模型-数据流图" aria-label="Permalink to &quot;功能模型（数据流图)&quot;">​</a></h4><p>功能、过程、数据流动路径</p><p>DFD 典型特征（一眼认出）：<strong>必有箭头</strong>（数据在移动）、<strong>必有加工</strong>（动词命名：验证、计算、查询）、不会出现条件判断（没有菱形，没有“是/否”分支）、<strong>不会出现状态</strong>（不会写“空闲/忙碌”）、<strong>数据存储只会被箭头连</strong>（不画字段细节）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234620.png" alt="image.png"></p><h4 id="行为模型-状态转换图" tabindex="-1">行为模型（状态转换图） <a class="header-anchor" href="#行为模型-状态转换图" aria-label="Permalink to &quot;行为模型（状态转换图）&quot;">​</a></h4><p>状态、事件、状态转换</p><p>最基础的形状（3个符号）</p><table tabindex="0"><thead><tr><th>符号</th><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>圆角矩形</td><td>状态</td><td>系统在某个时刻的样子（形容词/名词）</td></tr><tr><td>箭头</td><td>转换</td><td>从一个状态到另一个状态</td></tr><tr><td>箭头上文字</td><td>事件/条件</td><td>什么事触发了这个变化（格式：事件 [条件] / 动作）</td></tr></tbody></table><h4 id="数据模型-e-r-图" tabindex="-1">数据模型（E - R 图） <a class="header-anchor" href="#数据模型-e-r-图" aria-label="Permalink to &quot;数据模型（E - R 图）&quot;">​</a></h4><p>一般是数据建模的时候用，比如数据库的字段之类的</p><p>实体、属性、关系</p><p><strong>静态</strong>（数据结构，不随时间变化）</p><h4 id="数据字典" tabindex="-1">数据字典 <a class="header-anchor" href="#数据字典" aria-label="Permalink to &quot;数据字典&quot;">​</a></h4><p>数据元素、结构、定义</p><p><strong>静态定义</strong>（解释性）</p><h3 id="面向对象的分析方法" tabindex="-1">面向对象的分析方法 <a class="header-anchor" href="#面向对象的分析方法" aria-label="Permalink to &quot;面向对象的分析方法&quot;">​</a></h3><h4 id="uml-关系" tabindex="-1">UML 关系 <a class="header-anchor" href="#uml-关系" aria-label="Permalink to &quot;UML 关系&quot;">​</a></h4><ul><li>依赖</li><li>关联</li><li>泛化</li><li>实现</li><li>组合</li><li>聚合</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234739.png" alt="image.png"></p><h4 id="uml-图" tabindex="-1">UML 图 <a class="header-anchor" href="#uml-图" aria-label="Permalink to &quot;UML 图&quot;">​</a></h4><ul><li>用例图</li><li>类图</li><li>活动图</li><li>状态图</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234837.png" alt="image.png"></p><h3 id="面向对象分析模型" tabindex="-1">面向对象分析模型 <a class="header-anchor" href="#面向对象分析模型" aria-label="Permalink to &quot;面向对象分析模型&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234932.png" alt="image.png"></p><h3 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h3><h4 id="练习题1" tabindex="-1">练习题1 <a class="header-anchor" href="#练习题1" aria-label="Permalink to &quot;练习题1&quot;">​</a></h4><p>某现代农业种植基地为进一步提升农作物种植过程的智能化，欲开发智慧农业平台，集管理和销售于体，该平台的主要功能有：</p><ul><li>1.信息维护。农业专家对农作物、环境等监测数据的监控处理规则进行维护。</li><li>2.数据采集。获取传感器上传的农作物长势、土壤墒情、气候等连续监测数据，解析后将监测信息进行数据处理、可视化和存储等操作。</li><li>3.数据处理。对实时监测信息根据监控处理规则进行监测分析，将分析结果进行可视化并进行存储、远程控制对历史监测信息进行综合统计和预测，将预测信息进行可视化和存储。</li><li>4.远程控制。根据监控处理规则对分析结果进行判定，依据判定结果自动对控制器进行远程控制。平台也可以根据农业人员提供的控制信息对控制器进行远程控制。</li><li>5.可视化。实时向农业人员展示监测信息：实时给农业专家展示统计分析结果和预测信息或根据农业专家请求进行展示。</li></ul><p>现采用结构化方法对智慧农业平台进行分析与设计，获得如图所示的0层数据流图。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260522234038.png" alt="image.png"></p><ul><li>问题1(9分)：请给出数据流图的定义及父图和子图数据守恒的三个原则</li><li>问题2(8分)：根据描述，给出图中的E1-E4及D1-D4</li><li>问题3(8分)：根据说明和图中术语，补充图中缺失的数据流及其起点和终点。</li></ul><hr><p>答案：</p><p>问题1：</p>',38)),t("p",null,[l[1]||(l[1]=i("数据流图",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[0]||(l[0]=[i("从数据传递和加工的角度，利用图形符号通过逐层细分描述系统内各个部件的功能和数据在它们之间传递的情况",-1)])]),_:1}),l[2]||(l[2]=i("，来说明系统所完成的功能。",-1))]),l[33]||(l[33]=t("p",null,"父图和子图守恒原则：",-1)),t("ul",null,[t("li",null,[l[5]||(l[5]=i("(1)父图中",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[3]||(l[3]=[i("流入子图的数据流必须与子图输入数据流一致",-1)])]),_:1}),l[6]||(l[6]=i("：子图的",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[4]||(l[4]=[i("所有输入数据流必须是父图中相应加工的输入数据流",-1)])]),_:1}),l[7]||(l[7]=i("。",-1))]),t("li",null,[l[10]||(l[10]=i("(2)父图中",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[8]||(l[8]=[i("流出子图的数据流必须与子图输出数据流一致",-1)])]),_:1}),l[11]||(l[11]=i("：子图的所有",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[9]||(l[9]=[i("输出数据流必须是父图中相应加工的输出数据流",-1)])]),_:1}),l[12]||(l[12]=i("。",-1))]),t("li",null,[l[14]||(l[14]=i("(3)子图内部的数据流必须与父图无关：",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[13]||(l[13]=[i("子图内部的数据流不应出现在父图中，父图只关心子图的输入输出",-1)])]),_:1}),l[15]||(l[15]=i("。",-1))])]),l[34]||(l[34]=t("hr",null,null,-1)),l[35]||(l[35]=t("p",null,"问题2：",-1)),t("ul",null,[l[29]||(l[29]=o("<li><p>E1:传感器</p></li><li><p>E2:农业专家</p></li><li><p>E3:农业人员</p></li><li><p>E4:控制器</p></li><li><p>D1:监控处理规则表</p></li><li><p>D2:监测信息表</p></li><li><p>D3:分析结果表</p></li><li><p>D4:预测信息表</p></li>",8)),t("li",null,[t("p",null,[l[18]||(l[18]=i("1.信息维护。",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[16]||(l[16]=[i("农业专家",-1)])]),_:1}),l[19]||(l[19]=i("对农作物、环境等监测数据的",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[17]||(l[17]=[i("监控处理规则",-1)])]),_:1}),l[20]||(l[20]=i("进行维护。",-1))])]),t("li",null,[t("p",null,[l[22]||(l[22]=i("2.数据采集。获取",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[21]||(l[21]=[i("传感器",-1)])]),_:1}),l[23]||(l[23]=i("上传的农作物长势、土壤墒情、气候等连续监测数据，解析后将监测信息进行数据处理、可视化和存储等操作。",-1))])]),l[30]||(l[30]=t("li",null,[t("p",null,"3.数据处理。对实时监测信息根据监控处理规则进行监测分析，将分析结果进行可视化并进行存储、远程控制对历史监测信息进行综合统计和预测，将预测信息进行可视化和存储。")],-1)),t("li",null,[t("p",null,[l[26]||(l[26]=i("4.远程控制。根据监控处理规则对分析结果进行判定，依据判定结果自动对",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[24]||(l[24]=[i("控制器",-1)])]),_:1}),l[27]||(l[27]=i("进行远程控制。平台也可以根据",-1)),a(r,{color:"#ff0000"},{default:n(()=>[...l[25]||(l[25]=[i("农业人员",-1)])]),_:1}),l[28]||(l[28]=i("提供的控制信息对控制器进行远程控制。",-1))])]),l[31]||(l[31]=t("li",null,[t("p",null,"5.可视化。实时向农业人员展示监测信息：实时给农业专家展示统计分析结果和预测信息或根据农业专家请求进行展示。")],-1))]),l[36]||(l[36]=o('<hr><p>问题3：</p><table tabindex="0"><thead><tr><th>数据流</th><th>起点</th><th>终点</th></tr></thead><tbody><tr><td>规则</td><td>D1</td><td>P4</td></tr><tr><td>分析结果与预测信息</td><td>P3</td><td>P5</td></tr><tr><td>历史监测信息</td><td>D2</td><td>P3</td></tr><tr><td>请求</td><td>E2</td><td>P5</td></tr></tbody></table><hr><h4 id="练习题2" tabindex="-1">练习题2 <a class="header-anchor" href="#练习题2" aria-label="Permalink to &quot;练习题2&quot;">​</a></h4><p>设计一个电力风险管理系统的类图。该系统管理以下核心风险信息：</p><ul><li>电网风险信息(GridNetRisk)：涉及电网运行中的风险评估和监控。</li><li>基建风险信息(InfraRisk)：涉及电力基础设施（如变电站、输电线路）的风险管理。</li><li>工作风险信息(WorkRisk):涉及现场作业安全和工作流程中的风险控制。</li></ul><p>系统还提供风险分析功能(RiskAnalysis),并支持对分析结果的打印管理(PrintManager)和导出 Excel管理(ExportManager)。此外，系统包含一个通用警报类(GeneralAlarm)用于处理风险事件警报。所有风险信息通过一个主类(RiskManager)进行统一管理。</p><p>该系统类图如下图所示：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260522235506.png" alt="image.png"></p><p>类名选项如下：</p><ul><li>a:WorkRisk</li><li>b:GridNetRisk</li><li>c:InfraRisk</li><li>d:RiskAnalysis</li><li>e:PrintManager</li><li>f:ExportManager</li><li>g:GeneralAlarm</li><li>h: RiskManager</li></ul><p>基于上述系统描述和类图，回答以下问题：</p><ul><li>问题1：在类图中，从选项a ~ h中选择合适的类名填写16处空白位置。要求说明选择理由。</li><li>问题2：类与类之间存在哪些关系？请按照耦合度从高到低排序。并基于类图描述，找出类图中箭头与类关系对应错误的地方（至少一处)，说明错误原因及正确关系。</li><li>问题3：UML中有哪些主要视图？这些视图分别由哪些UML图组成？</li></ul><hr><p>答案：</p><p>问题1：</p><ul><li>1:a (WorkRisk)</li><li>2:c (InfraRisk)</li><li>3:b (GridNetRisk)</li><li>4:e (PrintManager)</li><li>5:f (ExportManager)</li><li>6:d (RiskAnalysis)</li></ul><p>问题2：</p><p>类之间有六种关系，耦合度从高到低排序及定义如下：</p><ul><li>实现。耦合度最高：实现类必须完全遵循接口的契约，接口的任何变更都会强制实现类修改。</li><li>泛化。高耦合：子类继承父类的实现细节，父类修改可能直接破坏子类功能。</li><li>组合。强依赖：部分对象的生命周期完全由整体对象控制（同生共死）。</li><li>聚合。中度耦合：部分对象可独立于整体对象存在，但仍有从属关系。</li><li>关联。低耦合：类间通过引用交互（如成员变量），但无生命周期依赖。</li><li>依赖。耦合度最低：临时性使用（如方法参数、局部变量），无长期引用。</li></ul><p>类图中箭头与关系对应错误及原因：</p><ul><li>错误位置：6(RiskAnalysis)到类 GeneralAlarm 的箭头表示泛化关系（继承）。</li><li>错误原因：系统描述中，GeneralAlarm是通用警报类，而RiskAnalysis是风险分析功能，两者无继承关系。RiskAnalysis应使用GeneralAlarm(依赖或关联)，而不是继承它。题干中，GeneralAlarm处理风险事件警报，而RiskAnalysis负责分析逻辑，继承关系不符合职责分离原则(RiskAnalysis不是一种警报)。</li><li>正确关系：应改为关联关系。</li></ul><p>问题3：</p><p>UML有五种视图，其与UML图对应关系如下：</p><ul><li>逻辑视图：类图、对象图</li><li>实现视图：构件图、复合结构图</li><li>进程视图：时序图、活动图、状态图</li><li>部署视图：部署图</li><li>用例视图：用例图</li></ul><hr>',27))])}const q=s(u,[["render",f]]);export{R as __pageData,q as default};
